repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('lodge', 14), ('plaza', 35), ('grand', 8), ('lodge', 19), ('grand', 57), ('plaza', 24)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.lookup.py:
"""Finding bookings by hotel."""


def bookings_for(bookings, hotel):
    """Return the bookings whose hotel matches, ignoring upper and lower case and spaces at either end."""
    return [x for x in bookings if x.hotel == hotel]


def has_hotel(bookings, hotel):
    """Return True when at least one booking matches the hotel."""
    return len(bookings_for(bookings, hotel)) > 0


def group_by_hotel(bookings):
    """Return a dict from hotel to the list of bookings with that hotel."""
    groups = {}
    for x in bookings:
        groups.setdefault(x.hotel, []).append(x)
    return groups
